ys = np.linspace(0, 180, ny + 1)

def node_id(ix, iy):
    return iy * (nx + 1) + ix

n_nodes = (nx + 1) * (ny + 1)

# Openings:
# RO-1: X in [96, 156], Y in [108, 148]
# RO-2: X in [36, 116], Y in [36, 56]
def is_in_opening(xc, yc):
    if 96.0 < xc < 156.0 and 108.0 < yc < 148.0:
        return True
    if 36.0 < xc < 116.0 and 36.0 < yc < 56.0:
        return True
    return False

def get_zone(xc, yc):
    col = int(xc // 60.0) # 0..3
    row = int(yc // 60.0) # 0..2
    return f'"'"'Z{row * 4 + col + 1}'"'"'

# Verify zone active element counts and areas
zone_counts = {f'"'"'Z{i}'"'"': 0 for i in range(1, 13)}
for iy in range(ny):
    for ix in range(nx):
        xc, yc = (ix + 0.5) * dx, (iy + 0.5) * dy
        if not is_in_opening(xc, yc):
